mapper.select:
SELECT dvc.id, dvc.version_id AS versionId, dvc.user_id AS userId, dvc.contributor_name AS contributorName, dvc.contributor_role AS contributorRole, DATE_FORMAT(dvc.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, u.uid AS uid, u.nickname AS nickname, u.avatar AS avatar, COALESCE(u.nickname, dvc.contributor_name, '匿名') AS displayName FROM dialogue_version_contributor dvc LEFT JOIN sys_user u ON u.id = dvc.user_id
AND dvc.version_id = #{query.versionId}
AND dvc.user_id = #{query.userId}
AND dvc.contributor_role = #{query.contributorRole}
ORDER BY dvc.created_at DESC, dvc.id DESC

mapper.update:
UPDATE dialogue_version_contributor
version_id = #{versionId}, user_id = #{userId}, contributor_name = #{contributorName}, contributor_role = #{contributorRole},
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM dialogue_version_contributor
WHERE version_id = #{versionId}
  AND user_id = #{userId}

SELECT COUNT(*)
FROM dialogue_version_contributor
WHERE version_id = #{versionId}
  AND user_id IS NULL
  AND contributor_name = #{contributorName}

SELECT COUNT(*)
FROM dialogue_version_contributor
WHERE version_id = #{versionId}
  AND user_id = #{userId}
  AND contributor_role = #{role}

SELECT dvc.id, dvc.version_id AS versionId, dvc.user_id AS userId, dvc.contributor_name AS contributorName, dvc.contributor_role AS contributorRole, DATE_FORMAT(dvc.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, u.uid AS uid, u.nickname AS nickname, u.avatar AS avatar, COALESCE(u.nickname, dvc.contributor_name, '匿名') AS displayName FROM dialogue_version_contributor dvc LEFT JOIN sys_user u ON u.id = dvc.user_id WHERE dvc.version_id IN
#{vid}
ORDER BY dvc.version_id, dvc.contributor_role, dvc.id
